let themeFirmwareIdentity="",themeIdentityReadInFlight=false;
function getStoredTheme(){try{return JSON.parse(localStorage.getItem("firmwareTheme")||"null")}catch(e){return null}}
function setStoredTheme(t){if(themeFirmwareIdentity)try{localStorage.setItem("firmwareTheme",JSON.stringify({identity:themeFirmwareIdentity,theme:t}))}catch(e){}}
function applyTheme(t){document.documentElement.setAttribute("data-theme",t);const b=document.getElementById("themeBtn");if(b)b.textContent=t==="light"?"夜间":"日间"}
function toggleTheme(){if(!themeFirmwareIdentity)return;const cur=document.documentElement.getAttribute("data-theme")==="light"?"light":"dark";const next=cur==="light"?"dark":"light";applyTheme(next);setStoredTheme(next)}
function syncFirmwareTheme(device){
  if(!device||!device.chipId||!/^[a-f0-9]{64}$/i.test(device.appElfSha256||""))return;
  const identity=String(device.chipId)+":"+device.appElfSha256.toLowerCase();
  if(identity===themeFirmwareIdentity)return;
  const saved=getStoredTheme(),firstIdentity=!themeFirmwareIdentity;
  themeFirmwareIdentity=identity;
  const theme=firstIdentity&&saved&&saved.identity===identity&&saved.theme==="dark"?"dark":"light";
  applyTheme(theme);setStoredTheme(theme);
  const button=document.getElementById("themeBtn");if(button)button.disabled=false;
}
async function refreshFirmwareTheme(){
  if(document.hidden||otaBusy||themeIdentityReadInFlight)return;
  themeIdentityReadInFlight=true;
  try{const status=await fetchDashboardJson("/system_status",5000);if(!otaBusy)syncFirmwareTheme(status.device)}catch(e){}
  finally{themeIdentityReadInFlight=false}
}
applyTheme("light");
{const button=document.getElementById("themeBtn");if(button)button.disabled=true}
