function applyCanPinLayoutStatus(s){if(!s||s.ok!==true)return false;const stored=Number(s.layout);if(!Number.isInteger(stored)||stored<0||stored>2)return false;canPinLayoutStored=stored;canPinLayoutLoaded=true;const select=document.getElementById("canPinLayoutSelect");if(select&&document.activeElement!==select)select.value=String(stored);if(Array.isArray(s.pins)){s.pins.forEach((pin,index)=>{if(index>=3||!pin)return;const label="GPIO"+Number(pin.tx)+" TX / GPIO"+Number(pin.rx)+" RX",bus=document.getElementById("canPinText"+index),route=canDiagnosticRoutes[index],diag=document.getElementById(route.prefix+"BoardPins");if(bus)bus.textContent=label;route.boardPins=label;if(diag)diag.textContent=label})}const active=Number(s.active)===1?"B组":"A组",source=String(s.source||"");let sourceText;if(source==="manual")sourceText="手动固定";else if(source==="auto_a"||source==="auto_b")sourceText="自动识别到有效帧";else if(source==="fallback_a")sourceText="尚未识别，暂按 A 运行";else if(source==="probe_failed")sourceText="探测失败，CAN 未启动";else sourceText=s.confirmed?"来源已确认":"来源未确认";const storedName=String(s.storedName||"Auto"),storedText=storedName==="A"?"固定 A":storedName==="B"?"固定 B":"自动";const state=document.getElementById("canPinLayoutState");if(state){let text=source==="probe_failed"?"CAN 未启动（线序探测失败；候选线序："+active+"）":"当前生效："+active+"（"+sourceText+"）";if(s.pendingRestart)text+="；保存的模式 "+storedText+"，重启后生效";state.textContent=text}return true}
