async function saveCanPinLayout(){if(canPinLayoutBusy)return;const select=document.getElementById("canPinLayoutSelect");if(!select)return;if(!canPinLayoutLoaded){showResult("线序状态不可用，请刷新页面后重试");setCanPinLayoutControlsDisabled(true);return}if(otaBusy){showResult("OTA 升级期间不能修改线序");setCanPinLayoutControlsDisabled(true);return}const requested=String(select.value);if(!["0","1","2"].includes(requested)){select.value=String(canPinLayoutStored);showResult("线序保存失败：线序选项无效");return}canPinLayoutBusy=true;setCanPinLayoutControlsDisabled(true);let postResult=null;try{const response=await fetch("/can_pin_layout",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"layout="+encodeURIComponent(requested)}),body=await response.text();let result={};try{result=body?JSON.parse(body):{}}catch(e){}postResult=result;if(!response.ok||result.ok!==true||result.persistence!=="stored"||!applyCanPinLayoutStatus(result))throw new Error(result.error||"persistence_not_stored");showResult("线序设置已写入Flash，重启后生效")}catch(e){const savedButRestoreFailed=e.message==="can_restore"&&postResult&&postResult.saved===true;const refreshed=await loadCanPinLayout();const errors={ota_busy:"OTA 正在进行",boot_validation_pending:"新固件启动验证期间不能修改",invalid_layout:"线序选项无效",flash_write:"写入 Flash 失败",can_quiesce:"CAN 未能安全停止",can_restore:"CAN 恢复失败"};if(savedButRestoreFailed){showResult("线序已写入Flash，但CAN恢复失败；"+(refreshed?"已刷新保存状态，当前生效线序仍按页面显示":"无法刷新保存状态，请重启后核对"))}else{const knownFailure=Object.prototype.hasOwnProperty.call(errors,e.message);showResult("线序保存失败："+(knownFailure?errors[e.message]:"结果未确认")+(knownFailure?"":refreshed?"；已重新读取设备保存状态":"；无法重新读取设备保存状态"))}}finally{canPinLayoutBusy=false;setCanPinLayoutControlsDisabled(otaBusy)}}
function canDiagnosticModels(current,previous){const buses=Array.isArray(current&&current.buses)?current.buses:[],oldBuses=Array.isArray(previous&&previous.buses)?previous.buses:[],elapsed=previous?Math.max(0,Number(current.capturedAtMs)-Number(previous.capturedAtMs)):0,oldByController=new Map(oldBuses.map(bus=>[Number(bus.controller),bus]));return canDiagnosticRoutes.map(route=>{const bus=buses.find(item=>Number(item.controller)===route.controller)||null,old=oldByController.get(route.controller),rate=key=>bus&&old&&elapsed>0?Math.max(0,Math.round((Number(bus[key]||0)-Number(old[key]||0))*1000/elapsed)):null;return {...route,bus,rxRate:rate("rxCount"),txRate:rate("txCount")}})}
