function canExperimentRuleMarkup(index){let bytes="";for(let byte=0;byte<8;byte++){const bits=kind=>{let value="";for(let bit=7;bit>=0;bit--)value+='<button type="button" class="canExperimentBit" data-ce-kind="'+kind+'" data-byte="'+byte+'" data-bit="'+bit+'" data-value="-" onclick="canExperimentCycleBit(this)">'+bit+':·</button>';return value};bytes+='<div class="canExperimentByte"><div class="canExperimentByteTop"><b>B'+byte+' <span data-ce-source-byte="'+byte+'">--</span>→<span data-ce-output-byte="'+byte+'">--</span></b><input data-ce-byte-edit="'+byte+'" maxlength="2" placeholder="整字节目标" onchange="canExperimentApplyWholeByte(this,\'edit\')"><input data-ce-byte-match="'+byte+'" maxlength="2" placeholder="原值条件" onchange="canExperimentApplyWholeByte(this,\'match\')"></div><small>修改 bit（·保持 / 0 / 1）</small><div class="canExperimentByteBits">'+bits("edit")+'</div><small>匹配 bit（·不限 / 0 / 1）</small><div class="canExperimentByteBits">'+bits("match")+'</div></div>'}
  return '<section class="canExperimentRule" data-ce-rule><div class="canExperimentRuleHead"><h3>规则 <span data-ce-rule-number>'+(index+1)+'</span></h3><div><button data-ce-confirm-source type="button" onclick="canExperimentConfirmSource(this)" disabled>确认帧来源</button><button class="warn" type="button" onclick="canExperimentRemoveRule(this)">删除</button></div></div><div class="canExperimentSourceGrid"><label>标准 CAN ID（HEX）<input data-ce-field="id" type="text" maxlength="5" value="" placeholder="例如 3FD"></label><label>线路<div class="canExperimentBusPick"><span>CAN0 13/14</span><input data-ce-bus="1" type="checkbox"><span>CAN1 9/10</span><input data-ce-bus="2" type="checkbox"><span>CAN2 2/3</span><input data-ce-bus="4" type="checkbox"></div></label><label>已确认 DLC<input data-ce-field="dlc" type="number" min="0" max="8" value="0" readonly></label><label>发送方式<select data-ce-field="mode"><option value="0">单次</option><option value="1">跟随原始帧</option><option value="2">固定周期</option></select></label></div><div class="canExperimentSettings"><label>周期 ms<input data-ce-field="period" type="number" min="5" max="60000" value="100"></label><label>模板有效 ms（0自动）<input data-ce-field="timeout" type="number" min="0" max="5000" value="0"></label><label>要求所选线路同时就绪<input data-ce-field="strict" type="checkbox"></label><label>接管对应内置发送<input data-ce-field="takeover" type="checkbox" checked></label><label>发送等级<select data-ce-field="priority"><option value="255">继承原报文等级</option><option value="1">新增报文 P1</option><option value="2">新增报文 P2</option><option value="3">新增报文 P3</option></select></label><label>跟随延迟 μs（0立即）<input data-ce-field="delayUs" type="number" min="0" max="5000000" value="0"></label></div><details class="featureHelp"><summary aria-label="CAN 规则与接管说明">?</summary><div>接管范围为所选线路、ID、DLC；3FD / 3C2 可用未修改的 MUX 匹配位缩小范围，其他匹配位仅筛选来源。已有报文按线路 / ID / MUX 继承等级，新增报文可选 P1/P2/P3。P0 仅限 CH 3FD MUX0，仍由原 fsd_p0 任务发送；准备工作在 can_rt，实际端到端延迟以下方回执为准。接管不能修改 MUX 位。</div></details><div class="canExperimentBytes">'+bytes+'</div><details class="advancedSettings"><summary>高级：计数器与 SUM / XOR / CRC8</summary><div class="canExperimentSettings"><label>计数器<select data-ce-field="counterMode"><option value="0">不处理</option><option value="1">原值偏移</option><option value="2">独立自增</option></select></label><label>字节<input data-ce-field="counterByte" type="number" min="0" max="7" value="0"></label><label>起始 bit<input data-ce-field="counterBit" type="number" min="0" max="7" value="0"></label><label>宽度<input data-ce-field="counterWidth" type="number" min="1" max="8" value="4"></label><label>步长<input data-ce-field="counterStep" type="number" min="1" max="255" value="1"></label><label>初值<input data-ce-field="counterInitial" type="number" min="0" max="255" value="0"></label><label>最小 / 最大<input data-ce-field="counterMin" type="number" min="0" max="255" value="0"><input data-ce-field="counterMax" type="number" min="0" max="255" value="15"></label><label>原值偏移<input data-ce-field="counterOffset" type="number" min="-128" max="127" value="0"></label><label>校验<select data-ce-field="checksumMode"><option value="0">不处理</option><option value="1">SUM</option><option value="2">XOR</option><option value="3">CRC8</option></select></label><label>参与字节<div class="canExperimentBusPick">'+Array.from({length:8},(_,i)=>'<span>B'+i+'</span><input data-ce-checksum-byte="'+i+'" type="checkbox" checked>').join("")+'</div></label><label>输出字节<input data-ce-field="checksumOutput" type="number" min="0" max="7" value="7"></label><label>加值 HEX<input data-ce-field="checksumAdd" type="text" maxlength="2" value="00"></label><label>最终 XOR HEX<input data-ce-field="checksumXor" type="text" maxlength="2" value="00"></label><label>CRC 多项式 HEX<input data-ce-field="crcPoly" type="text" maxlength="2" value="1D"></label><label>CRC 初值 HEX<input data-ce-field="crcInitial" type="text" maxlength="2" value="FF"></label><label>CRC 输入反射<input data-ce-field="crcRefIn" type="checkbox"></label><label>CRC 输出反射<input data-ce-field="crcRefOut" type="checkbox"></label><label>CRC 包含 CAN ID<input data-ce-field="crcIncludeId" type="checkbox"></label></div></details><div data-ce-lanes class="canExperimentLanes"><div class="canExperimentLane">尚未收到来源帧</div></div></section>'
}
function canExperimentRules(){return Array.from(document.querySelectorAll("#canExperimentRules [data-ce-rule]"))}
function canExperimentAddRule(initial=false){const host=document.getElementById("canExperimentRules");if(!host)return;const rules=canExperimentRules();if(rules.length>=4){canExperimentMessage("最多 4 条规则",true);return}host.insertAdjacentHTML("beforeend",canExperimentRuleMarkup(rules.length));if(!initial)canExperimentInvalidate()}
function canExperimentRemoveRule(button){const rules=canExperimentRules();if(rules.length<=1){canExperimentMessage("至少保留 1 条规则",true);return}button.closest("[data-ce-rule]").remove();canExperimentRules().forEach((rule,index)=>rule.querySelector("[data-ce-rule-number]").textContent=index+1);canExperimentInvalidate()}
function canExperimentCycleBit(button){const next={"-":"0","0":"1","1":"-"}[button.dataset.value]||"-";button.dataset.value=next;button.textContent=button.dataset.bit+":"+(next==="-"?"·":next);canExperimentInvalidate()}
function canExperimentApplyWholeByte(input,kind){const value=input.value.trim().toUpperCase(),rule=input.closest("[data-ce-rule]"),byte=input.dataset[kind==="edit"?"ceByteEdit":"ceByteMatch"];if(value!==""&&!/^[0-9A-F]{2}$/.test(value)){input.value="";canExperimentMessage("字节值请输入两位 HEX",true);return}rule.querySelectorAll('[data-ce-kind="'+kind+'"][data-byte="'+byte+'"]').forEach(button=>{const bit=Number(button.dataset.bit),state=value===""?"-":((parseInt(value,16)>>bit)&1?"1":"0");button.dataset.value=state;button.textContent=bit+":"+(state==="-"?"·":state)});canExperimentInvalidate()}
function canExperimentCompileBits(rule,kind){const mask=Array(8).fill(0),value=Array(8).fill(0);rule.querySelectorAll('[data-ce-kind="'+kind+'"]').forEach(button=>{const byte=Number(button.dataset.byte),bit=Number(button.dataset.bit),state=button.dataset.value;if(state!=="-"){mask[byte]|=1<<bit;if(state==="1")value[byte]|=1<<bit}});const hex=bytes=>bytes.map(v=>v.toString(16).padStart(2,"0").toUpperCase()).join("");return {mask:hex(mask),value:hex(value)}}
function canExperimentField(rule,name){return rule.querySelector('[data-ce-field="'+name+'"]')}
function canExperimentCollect(){const params=new URLSearchParams(),rules=canExperimentRules();if(!rules.length)throw new Error("至少需要一条规则");params.set("ruleCount",rules.length);rules.forEach((rule,index)=>{const id=canExperimentField(rule,"id").value.trim().replace(/^0x/i,"").toUpperCase();if(!/^[0-7]?[0-9A-F]{1,2}$/.test(id))throw new Error("规则 "+(index+1)+" 的 CAN ID 无效");let buses=0;rule.querySelectorAll("[data-ce-bus]:checked").forEach(input=>buses|=Number(input.dataset.ceBus));if(!buses)throw new Error("规则 "+(index+1)+" 未选择线路");params.set("id"+index,id);params.set("buses"+index,buses);["dlc","mode","period","timeout","delayUs","priority","counterMode","counterByte","counterBit","counterWidth","counterStep","counterInitial","counterMin","counterMax","counterOffset","checksumMode","checksumOutput","checksumAdd","checksumXor","crcPoly","crcInitial"].forEach(name=>params.set(name+index,canExperimentField(rule,name).value));params.set("strict"+index,canExperimentField(rule,"strict").checked?"1":"0");params.set("takeover"+index,canExperimentField(rule,"takeover").checked?"1":"0");const match=canExperimentCompileBits(rule,"match"),edit=canExperimentCompileBits(rule,"edit");params.set("matchMask"+index,match.mask);params.set("matchValue"+index,match.value);params.set("editMask"+index,edit.mask);params.set("editValue"+index,edit.value);let checksumBytes=0;rule.querySelectorAll("[data-ce-checksum-byte]:checked").forEach(input=>checksumBytes|=1<<Number(input.dataset.ceChecksumByte));params.set("checksumBytes"+index,checksumBytes.toString(16).toUpperCase());["crcRefIn","crcRefOut","crcIncludeId"].forEach(name=>params.set(name+index,canExperimentField(rule,name).checked?"1":"0"))});return params}
function canExperimentMessage(text,bad=false){const element=document.getElementById("canExperimentMessage");if(!element)return;element.textContent=text;element.style.color=bad?"var(--bad)":"var(--muted)"}
function canExperimentInvalidate(){if(canExperimentState==="running"||canExperimentState==="stopping")return;canExperimentDirty=true;canExperimentGeneration=0;const start=document.getElementById("canExperimentStartButton");if(start)start.disabled=true;canExperimentMessage("内容已修改，请重新执行对应确认。")}
async function canExperimentRequest(path,params,method="POST"){const response=await fetch(path,{method,body:method==="GET"?undefined:params,cache:"no-store"}),json=await response.json().catch(()=>({}));if(!response.ok||json.ok===false)throw new Error(json.error||("HTTP "+response.status));return json}
async function canExperimentListen(){try{const params=canExperimentCollect();await canExperimentRequest("/api/can-experiment/listen",params);canExperimentDirty=false;canExperimentGeneration=0;canExperimentMessage("正在按线路监听真实帧；每路连续 3 帧 DLC 稳定后确认来源。");await canExperimentPollStatus(true)}catch(error){canExperimentMessage("监听失败："+error.message,true)}}
async function canExperimentConfirmSource(button){const rule=button.closest("[data-ce-rule]"),index=canExperimentRules().indexOf(rule),params=new URLSearchParams({rule:String(index)});try{const result=await canExperimentRequest("/api/can-experiment/source/confirm",params);canExperimentField(rule,"dlc").value=result.dlc;canExperimentMessage("规则 "+(index+1)+" 来源已确认，DLC="+result.dlc+"。现在设置修改内容。");await canExperimentPollStatus(true)}catch(error){canExperimentMessage("来源确认失败："+error.message,true)}}
async function canExperimentValidate(){try{const result=await canExperimentRequest("/api/can-experiment/validate",canExperimentCollect());canExperimentDirty=false;canExperimentGeneration=Number(result.generation||0);const warnings=(result.warnings||[]).map(item=>item.message).filter(Boolean);const start=document.getElementById("canExperimentStartButton");if(start)start.disabled=!canExperimentGeneration;canExperimentMessage("修改内容已确认，版本 "+canExperimentGeneration+(warnings.length?"；提示："+warnings.join("；"):"。"));await canExperimentPollStatus(true)}catch(error){canExperimentGeneration=0;canExperimentMessage("内容确认失败："+error.message,true)}}
async function canExperimentStart(){if(!canExperimentGeneration){canExperimentMessage("请先确认修改内容",true);return}try{const params=canExperimentCollect();params.set("confirmedGeneration",String(canExperimentGeneration));await canExperimentRequest("/api/can-experiment/start",params);canExperimentMessage("实验已开启；可恢复异常只暂停对应线路。");await canExperimentPollStatus(true)}catch(error){canExperimentMessage("启动失败："+error.message,true)}}
async function canExperimentStop(){try{await canExperimentRequest("/api/can-experiment/stop",new URLSearchParams());canExperimentMessage("已请求停止，不再生成新实验帧。");await canExperimentPollStatus(true)}catch(error){canExperimentMessage("停止失败："+error.message,true)}}
function canExperimentStateLabel(state){return {stopped:"已停止",listening:"监听中",ready:"已确认",running:"运行中",stopping:"停止中",error_stopped:"错误停止"}[state]||state}
function canExperimentApplyStatus(status){
  canExperimentState=status.state||"stopped";
  const shouldHydrate=!canExperimentDirty&&Array.isArray(status.rules)&&status.rules.length&&canExperimentRules().every(rule=>!canExperimentField(rule,"id").value.trim());
  if(shouldHydrate)canExperimentLoadDraft(status,true);
  if(!canExperimentDirty)canExperimentGeneration=Number(status.generation||canExperimentGeneration||0);
  const active=["running","stopping"].includes(canExperimentState),listening=["listening","ready"].includes(canExperimentState),card=document.getElementById("canExperimentCard"),tag=document.getElementById("canExperimentHeaderState"),stop=document.getElementById("canExperimentHeaderStop"),start=document.getElementById("canExperimentStartButton");
  if(card)card.classList.toggle("canExperimentRunning",active);
  if(tag)tag.textContent=canExperimentStateLabel(canExperimentState);
  if(stop)stop.classList.toggle("hidden",!active);
  const locked=active;
  canExperimentRules().forEach(rule=>rule.querySelectorAll("input,select,button").forEach(input=>input.disabled=locked));
  const actions=document.querySelectorAll("#canExperimentCard .canExperimentActions button");
  actions.forEach(button=>{if(button!==start)button.disabled=locked&&!button.classList.contains("warn")});
  if(start)start.disabled=locked||canExperimentDirty||!["ready","stopped"].includes(canExperimentState)||!canExperimentGeneration;
  const grouped=new Map();
  (status.lanes||[]).forEach(lane=>{if(!grouped.has(Number(lane.rule)))grouped.set(Number(lane.rule),[]);grouped.get(Number(lane.rule)).push(lane)});
  canExperimentRules().forEach((rule,index)=>{
    const lanes=grouped.get(index)||[],host=rule.querySelector("[data-ce-lanes]"),confirmed=!!(status.sourceConfirmed||[])[index],sourceReady=lanes.length>0&&lanes.every(lane=>Number(lane.stableSourceFrames||0)>=3),confirm=rule.querySelector("[data-ce-confirm-source]");
    if(confirm){confirm.disabled=locked||!listening||confirmed||!sourceReady;confirm.title=confirmed?"来源已确认":(!listening?"请先开始监听":(!sourceReady?"所选每一路需连续收到 3 帧稳定来源":"确认帧来源"))}
    if(host)host.innerHTML=lanes.length?lanes.map(lane=>'<div class="canExperimentLane"><b>CAN'+({1:0,2:1,4:2}[lane.bus]??lane.bus)+' · '+lane.state+' · '+(Number(lane.priority)<4?'P'+lane.priority:'待匹配')+'</b><br>原始 '+(lane.source||"--")+'<br>修改 '+(lane.output||"--")+'<br>年龄 '+(lane.templateValid?lane.templateAgeMs+"ms":"未收到")+' · RX '+lane.rx+' · 稳定 '+Math.min(3,Number(lane.stableSourceFrames||0))+'/3 · 生成/接受/拒绝 '+lane.generated+'/'+lane.accepted+'/'+lane.rejected+' · 终态成功/失败 '+lane.terminalOk+'/'+lane.terminalFail+' · busy/stale/DLC '+lane.busySkip+'/'+lane.staleSkip+'/'+lane.dlcMismatch+' · 延迟模板替换 '+Number(lane.delayedSupersededCount||0)+'<br>RX→接受 μs 最近/最大 '+Number(lane.lastAcceptedLatencyUs||0)+'/'+Number(lane.maxAcceptedLatencyUs||0)+' · RX→终态 μs 最近/最大 '+Number(lane.lastTerminalLatencyUs||0)+'/'+Number(lane.maxTerminalLatencyUs||0)+'</div>').join(""):'<div class="canExperimentLane">尚未收到来源帧</div>';
    const lane=lanes[0],source=lane&&String(lane.source||"").split(" "),output=lane&&String(lane.output||"").split(" ");
    for(let byte=0;byte<8;byte++){const sourceNode=rule.querySelector('[data-ce-source-byte="'+byte+'"]'),outputNode=rule.querySelector('[data-ce-output-byte="'+byte+'"]');if(sourceNode)sourceNode.textContent=source&&source[byte]||"--";if(outputNode)outputNode.textContent=output&&output[byte]||"--"}
  });
  const summary=document.getElementById("canExperimentStatus");
  if(summary)summary.textContent="后台状态："+canExperimentStateLabel(canExperimentState)+" · generation "+Number(status.generation||0)+" · "+Number(status.ruleCount||0)+" 条规则 / "+Number(status.laneCount||0)+" 条线路 · 按原报文等级调度 · 内置发送接管 "+(status.takeoverActive?"生效":"已释放");
  syncCanExperimentPolling()
}
function canExperimentPollDelay(){if(currentAppPage!=="diag")return 0;const card=document.getElementById("canExperimentCard"),expanded=card&&!card.classList.contains("collapsed"),active=["listening","ready","running","stopping"].includes(canExperimentState);if(!expanded&&!active)return 0;return document.hidden||!expanded?1000:200}
function syncCanExperimentPolling(){if(canExperimentTimer){clearTimeout(canExperimentTimer);canExperimentTimer=null}const delay=canExperimentPollDelay();if(delay&&!canExperimentInFlight)canExperimentTimer=setTimeout(()=>canExperimentPollStatus(false),delay)}
async function canExperimentPollStatus(immediate=false){if(canExperimentInFlight)return;canExperimentInFlight=true;if(canExperimentTimer){clearTimeout(canExperimentTimer);canExperimentTimer=null}try{const status=await fetchDashboardJson("/api/can-experiment/status",5000);canExperimentFailures=0;canExperimentApplyStatus(status)}catch(error){if(!isDashboardReadCancelled(error)){canExperimentFailures++;canExperimentMessage("状态读取失败："+error.message,true)}}finally{canExperimentInFlight=false;const normal=canExperimentPollDelay(),delay=canExperimentFailures?Math.min(2000,500*Math.pow(2,canExperimentFailures-1)):normal;if(delay&&currentAppPage==="diag")canExperimentTimer=setTimeout(()=>canExperimentPollStatus(false),delay)}}
const canExperimentPresetPending=new Map();let canExperimentPresetPollTimer=null,canExperimentPresetPollCount=0,canExperimentPresetReadSequence=0;
function canExperimentPresetPersistence(data){
  for(const [slot,request] of canExperimentPresetPending){
    const entry=(data.slots||[]).find(item=>Number(item.slot)===slot);if(!entry)continue;
    if(Number(entry.generation)!==request.generation){canExperimentPresetPending.delete(slot);canExperimentMessage("槽 "+(slot+1)+" 已被后续修改替换，请查看当前预设",true);continue}
    if(!entry.persistencePending&&Number(entry.persistedGeneration)===request.generation){canExperimentPresetPending.delete(slot);canExperimentMessage((request.action==="delete"?"预设已删除":request.action==="rename"?"预设已重命名":"预设已保存")+"，已写入Flash")}
  }
}
function canExperimentTrackPreset(result,action){
  if(result.persistence==="stored"&&Number(result.persistedGeneration)===Number(result.generation)){canExperimentMessage("预设修改已写入Flash");return}
  if(result.persistence!=="pending"||!Number.isInteger(Number(result.slot))||!Number(result.generation))throw new Error("保存结果未确认");
  canExperimentPresetPending.set(Number(result.slot),{generation:Number(result.generation),action});canExperimentPresetPollCount=0;canExperimentMessage("预设修改已应用，等待写入Flash");
}
async function canExperimentLoadPresets(){
  const sequence=++canExperimentPresetReadSequence;
  try{const response=await fetch("/api/can-experiment/presets",{cache:"no-store"}),data=await response.json(),select=document.getElementById("canExperimentPresetSlot");if(!response.ok||sequence!==canExperimentPresetReadSequence)return;
    if(select){const selected=select.value;select.replaceChildren();for(const slot of data.slots||[]){const option=document.createElement("option");option.value=String(slot.slot);option.textContent="槽 "+(slot.slot+1)+(slot.occupied?" · "+(slot.valid?(slot.name||"未命名"):"数据损坏"):" · 空")+(slot.persistencePending?" · 待写入Flash":"");select.appendChild(option)}if([...select.options].some(option=>option.value===selected))select.value=selected}
    canExperimentPresetPersistence(data);return data;
  }catch(error){if(canExperimentPresetPending.size)canExperimentMessage("预设写入状态暂时无法确认",true)}
  finally{clearTimeout(canExperimentPresetPollTimer);canExperimentPresetPollTimer=null;if(canExperimentPresetPending.size&&canExperimentPresetPollCount++<30)canExperimentPresetPollTimer=setTimeout(()=>{if(!document.hidden&&!otaBusy)canExperimentLoadPresets()},1000)}
}
function canExperimentSetBits(rule,kind,maskText,valueText){const clean=text=>String(text||"").replace(/[^0-9A-F]/gi,"").padEnd(16,"0"),mask=clean(maskText),value=clean(valueText);for(let byte=0;byte<8;byte++){const m=parseInt(mask.slice(byte*2,byte*2+2),16)||0,v=parseInt(value.slice(byte*2,byte*2+2),16)||0;rule.querySelectorAll('[data-ce-kind="'+kind+'"][data-byte="'+byte+'"]').forEach(button=>{const bit=Number(button.dataset.bit),state=m&(1<<bit)?(v&(1<<bit)?"1":"0"):"-";button.dataset.value=state;button.textContent=bit+":"+(state==="-"?"·":state)})}}
function canExperimentLoadDraft(data,silent=false){const host=document.getElementById("canExperimentRules"),rules=Array.isArray(data.rules)?data.rules:[];if(!host||!rules.length)return;host.innerHTML="";rules.slice(0,4).forEach((item,index)=>{host.insertAdjacentHTML("beforeend",canExperimentRuleMarkup(index));const rule=canExperimentRules()[index];canExperimentField(rule,"id").value=Number(item.id||0).toString(16).toUpperCase();rule.querySelectorAll("[data-ce-bus]").forEach(input=>input.checked=(Number(item.buses||0)&Number(input.dataset.ceBus))!==0);["dlc","mode","period","timeout","delayUs","priority","counterMode","counterByte","counterBit","counterWidth","counterStep","counterInitial","counterMin","counterMax","counterOffset","checksumMode","checksumOutput","checksumAdd","checksumXor","crcPoly","crcInitial"].forEach(name=>{if(item[name]!==undefined)canExperimentField(rule,name).value=["checksumAdd","checksumXor","crcPoly","crcInitial"].includes(name)?Number(item[name]).toString(16).padStart(2,"0").toUpperCase():item[name]});canExperimentField(rule,"strict").checked=!!item.strict;canExperimentField(rule,"takeover").checked=!!item.takeover;canExperimentField(rule,"delayUs").value=item.delayUs||0;canExperimentField(rule,"priority").value=item.priority??255;["crcRefIn","crcRefOut","crcIncludeId"].forEach(name=>canExperimentField(rule,name).checked=!!item[name]);const checksumBytes=Number(item.checksumBytes||0);rule.querySelectorAll("[data-ce-checksum-byte]").forEach(input=>input.checked=(checksumBytes&(1<<Number(input.dataset.ceChecksumByte)))!==0);canExperimentSetBits(rule,"match",item.matchMask,item.matchValue);canExperimentSetBits(rule,"edit",item.editMask,item.editValue)});if(!silent){canExperimentDirty=true;canExperimentGeneration=0;canExperimentMessage("预设已载入草稿；不会自动确认或启动。")}syncCanExperimentPolling()}
async function canExperimentPresetAction(action){try{const select=document.getElementById("canExperimentPresetSlot"),name=document.getElementById("canExperimentPresetName"),params=action==="save"?canExperimentCollect():new URLSearchParams();params.set("slot",select.value);params.set("action",action);params.set("name",name.value.trim());const result=await canExperimentRequest("/api/can-experiment/presets",params);if(action==="load")canExperimentLoadDraft(result);else{canExperimentTrackPreset(result,action);await canExperimentLoadPresets()}}catch(error){canExperimentMessage("预设操作失败："+error.message,true)}}
async function canExperimentPresetDelete(){const select=document.getElementById("canExperimentPresetSlot"),params=new URLSearchParams({slot:select.value});try{const result=await canExperimentRequest("/api/can-experiment/presets",params,"DELETE");canExperimentTrackPreset(result,"delete");await canExperimentLoadPresets()}catch(error){canExperimentMessage("删除失败："+error.message,true)}}
