function setCardCollapsed(card,collapsed){const children=Array.from(card.children),head=children.find(e=>e.classList&&e.classList.contains("cardHead")),body=children.find(e=>e.classList&&e.classList.contains("cardBody"));card.classList.toggle("collapsed",collapsed);if(body)body.hidden=collapsed;if(head)head.setAttribute("aria-expanded",collapsed?"false":"true");if(typeof syncTorqueNagPolling==="function")syncTorqueNagPolling();if(typeof syncCanHotPolling==="function")syncCanHotPolling();if(typeof syncCanExperimentPolling==="function")syncCanExperimentPolling()}
function initCollapsibleCards(){const interactive="button,input,select,label,a,summary,details,textarea";document.querySelectorAll(".appPage>.card").forEach(card=>{if(card.dataset.collapsibleReady==="1")return;card.dataset.collapsibleReady="1";card.classList.add("collapsible");let head=Array.from(card.children).find(e=>e.classList&&e.classList.contains("cardHead"));if(!head){const directTitle=Array.from(card.children).find(e=>e.tagName==="H2"),profileTitle=card.querySelector(".profileTitle");head=document.createElement("div");head.className="cardHead"+(directTitle?" cardHeadSimple":"");card.insertBefore(head,directTitle||card.firstChild);if(directTitle)head.appendChild(directTitle);else head.innerHTML='<div class="cardTitle"><i>◆</i><div><h2>'+((profileTitle&&profileTitle.textContent)||"功能")+'</h2><p>点击展开或收起</p></div></div>'}const body=document.createElement("div");body.className="cardBody";while(head.nextSibling)body.appendChild(head.nextSibling);card.appendChild(body);const toggle=document.createElement("button");toggle.type="button";toggle.className="cardChevron";toggle.setAttribute("aria-label","展开或收起");toggle.textContent="⌄";head.appendChild(toggle);head.setAttribute("role","button");head.setAttribute("tabindex","0");const flip=()=>setCardCollapsed(card,!card.classList.contains("collapsed"));head.addEventListener("click",event=>{if(event.target.closest(interactive)&&!event.target.closest(".cardChevron"))return;event.stopPropagation();flip()});head.addEventListener("keydown",event=>{if(event.target===head&&(event.key==="Enter"||event.key===" ")){event.preventDefault();flip()}});card.addEventListener("click",event=>{if(!card.classList.contains("collapsed")||event.target.closest(interactive))return;setCardCollapsed(card,false)});setCardCollapsed(card,card.dataset.defaultExpanded!=="1")})}
function toggleFeatureHelp(card,panel,button){
  const show=panel.hidden||card.classList.contains("collapsed");
  if(show&&card.classList.contains("collapsed"))setCardCollapsed(card,false);
  panel.hidden=!show;button.setAttribute("aria-expanded",String(show));
}
function initFeatureHelp(){
  const selector=".cardTitle p,.featureDesc,.profileCopy,.profileNote,.route-note:not([data-live-note]),.presetHint,.gearFeatureCopy,.torqueNagHint,.sectionHint:not([id]),.safetyNote,.safetySectionHead p,.safetyToggleCopy>small,.safetyLaneHeading>span>small,.safetyStatusLabel>small,.torqueNagField>small,[data-help-copy],details.featureHelp,details.driverRules";
  document.querySelectorAll(".appPage>.card").forEach((card,index)=>{
    if(card.dataset.helpReady==="1")return;
    const head=Array.from(card.children).find(node=>node.classList.contains("cardHead")),body=Array.from(card.children).find(node=>node.classList.contains("cardBody"));
    if(!head||!body)return;
    const notes=Array.from(card.querySelectorAll(selector)).filter(node=>!node.parentElement.closest("details.featureHelp,details.driverRules")&&!node.closest("[data-live-note]"));
    if(!notes.length)return;
    const heading=head.querySelector("h2"),title=heading?heading.textContent.trim():"功能",panel=document.createElement("div");
    panel.className="featureHelpPanel";panel.id="featureHelpPanel-"+index;panel.hidden=true;panel.setAttribute("role","region");panel.setAttribute("aria-label",title+"功能说明");
    notes.forEach(node=>{
      const section=document.createElement("section"),topic=node.dataset.helpTopic||(node.tagName==="DETAILS"?node.querySelector("summary").getAttribute("aria-label"):null);
      if(topic){const label=document.createElement("h3");label.textContent=topic;section.appendChild(label)}
      if(node.tagName==="DETAILS"){
        if(node.id)section.id=node.id;
        Array.from(node.childNodes).filter(child=>child.nodeName!=="SUMMARY").forEach(child=>section.appendChild(child));node.remove();
      }else{
        // Only static prose is restored; conditional notes retain their live ID.
        if(!node.id)node.classList.remove("hidden");
        node.classList.add("featureHelpCopy");section.appendChild(node);
      }
      panel.appendChild(section);
    });
    const button=document.createElement("button");button.type="button";button.className="featureHelpButton";button.textContent="?";button.setAttribute("aria-label",title+"功能说明");button.setAttribute("aria-controls",panel.id);button.setAttribute("aria-expanded","false");
    button.addEventListener("click",event=>{event.stopPropagation();toggleFeatureHelp(card,panel,button)});
    panel.addEventListener("keydown",event=>{if(event.key==="Escape"){panel.hidden=true;button.setAttribute("aria-expanded","false");button.focus()}});
    if(heading){const row=document.createElement("div");row.className="featureHelpHeading";heading.parentNode.insertBefore(row,heading);row.append(heading,button)}else head.appendChild(button);
    body.insertBefore(panel,body.firstChild);card.dataset.helpReady="1";
  });
}
