function saveSeatSlotNames(){const names=Array.from(document.querySelectorAll("[data-seat-slot-name]")).map((input,index)=>input.value.trim()||defaultSeatSlotName(index));try{localStorage.setItem(seatSlotNamesStorageKey,JSON.stringify(names))}catch(e){}}
