function setVal(id,v){const e=document.getElementById(id);if(!e)return;if(id==="fsdWarningLaneModes"){const modes=(Number(v)&3)||1;e.value=modes;const standard=document.getElementById("fsdWarningLaneStandard"),severe=document.getElementById("fsdWarningLaneSevere");if(standard)standard.checked=!!(modes&1);if(severe)severe.checked=!!(modes&2);return}if(e.type==="checkbox")e.checked=!!v;else if(id==="v13LowSpeedOffsetPct"||id==="v13HighSpeedOffsetPct")e.value=Math.max(0,Math.min(60,Math.trunc(Number(v)||0)));else if(id==="speedDownStepKph")e.value=Math.max(1,Math.min(10,Math.round(Number(v)||1)));else if(id===fsdAutoStartSpeedKphId)e.value=Math.max(1,Math.min(120,Math.round(Number(v)||15)));else if(id===fsdAutoStartAvailableFramesId)e.value=Math.max(1,Math.min(10,Math.round(Number(v)||1)));else if(id==="v14CameraDisableDelaySec")e.value=Math.max(3,Math.min(10,Math.round(Number(v)||3)));else if(id==="gearAutoShiftMaxSpeedKph")e.value=Math.max(0,Math.min(8,Math.round(Number(v)||0)));else if(id==="speedOffsetDownSlewPctPerSec")e.value=Math.max(0,Math.min(20,Math.round(Number(v)||0)));else if(id in lightingNumericConfigRules)e.value=normalizeLightingConfigValue(id,v);else if(id==="speedOffsetMaxPctRaw"||id==="v14SpeedOffsetMaxPctRaw")e.value=Math.max(0,Math.min(60,Number(v||0)/4)).toFixed(2);else if(id==="dndSpeedPeriodMinMs"||id==="dndSpeedPeriodMaxMs")e.value=Number(v)/1000;else if(["gearParkSteeringThresholdDeciDeg","gearDriveReverseSteeringThresholdDeciDeg","bleObstacleSteeringThresholdDeciDeg"].includes(id))e.value=Math.max(1,Math.min(360,Number(v||0)/10));else e.value=v;if(id==="stalkControlVersion")updateFsdProtocolUi();if(id==="v14ManualDrivingProfileEnabled")updateV14DrivingProfileUi();if(id==="stableSpeedOffsetEnabled")updateStableSpeedUi();if(id==="v13SpaceToSpaceEnabled"||id==="stalkControlVersion")updateV13SpaceToSpaceUi();if(id==="dndSpeedPeriodicEnabled"||id==="dndScrollMode")updateDndSpeedPeriodicUi()}
