function getVal(e){if(e.type==="checkbox")return e.checked?1:0;if(e.id==="v13LowSpeedOffsetPct"||e.id==="v13HighSpeedOffsetPct")return Math.max(0,Math.min(60,Math.trunc(Number(e.value)||0)));if(e.id==="speedDownStepKph")return Math.max(1,Math.min(10,Math.round(Number(e.value)||1)));if(e.id===fsdAutoStartSpeedKphId)return Math.max(1,Math.min(120,Math.round(Number(e.value)||15)));if(e.id===fsdAutoStartAvailableFramesId)return Math.max(1,Math.min(10,Math.round(Number(e.value)||1)));if(e.id==="v14CameraDisableDelaySec")return Math.max(3,Math.min(10,Math.round(Number(e.value)||3)));if(e.id==="gearAutoShiftMaxSpeedKph")return Math.max(0,Math.min(8,Math.round(Number(e.value)||0)));if(e.id==="speedOffsetDownSlewPctPerSec")return Math.max(0,Math.min(20,Math.round(Number(e.value)||0)));if(e.id in lightingNumericConfigRules)return normalizeLightingConfigValue(e.id,e.value);if(e.id==="speedOffsetMaxPctRaw"||e.id==="v14SpeedOffsetMaxPctRaw")return Math.max(0,Math.min(240,Math.round((Number(e.value)||0)*4)));if(e.id==="dndSpeedPeriodMinMs"||e.id==="dndSpeedPeriodMaxMs")return Math.round((Number(e.value)||0)*1000);if(["gearParkSteeringThresholdDeciDeg","gearDriveReverseSteeringThresholdDeciDeg","bleObstacleSteeringThresholdDeciDeg"].includes(e.id))return Math.max(10,Math.min(3600,Math.round((Number(e.value)||0)*10)));return e.value}
