async function setFsdAutoStartMaster(enabled){
  if(fsdMasterSaveInFlight||otaBusy)return false;
  const master=document.getElementById("fsdAutoStartEnabled"),params=new URLSearchParams({enabled:enabled?"1":"0",fsdConfigRevision:String(fsdConfigRevision)});
  fsdMasterSaveInFlight=true;configEditGeneration++;if(master)master.disabled=true;
  if(autoSaveTimer){clearTimeout(autoSaveTimer);autoSaveTimer=null;autoSaveQueued=true}
  try{
    const r=await fetch("/fsd_auto_start/master",{method:"POST",body:params}),j=await r.json();
    if(j.ramApplied){fsdConfigRevision=Number(j.revision)>>>0;if(master)master.checked=!!j.enabled;fsdAutoStartResetChildIds.forEach(id=>{const e=document.getElementById(id);if(e)e.checked=!!j.enabled});updateFsdAutoStartUi()}
    if(!r.ok){
      if(j.error==="fsd_config_stale"){const current=await fetch("/config",{cache:"no-store"});if(current.ok)applyNormalizedFsdAutoStartConfig(await current.json());showResult("设置已变化，已刷新，请重试主开关操作")}
      else showResult(j.ramApplied?"主开关已应用，但未写入Flash，等待重试保存":"主开关设置失败");
      return false;
    }
    if(!j.ok||!j.ramApplied||j.persistence!=="stored")throw new Error("save_unconfirmed");if(typeof cloudMarkSettingsSaved==='function')cloudMarkSettingsSaved();
    showResult(enabled?"FSD 自动激活已启用并已写入Flash，三个子开关已开启":"FSD 自动激活及三个子开关已关闭并已写入Flash，驾驶位模拟保持独立设置");return true;
  }catch(e){showResult("FSD 自启动设置结果未确认，请刷新查看");return false}
  finally{fsdMasterSaveInFlight=false;if(master)master.disabled=false;if(autoSaveQueued){autoSaveQueued=false;scheduleAutoSaveRetry()}}
}
