if(val("twaiTxQueue")>14)add(2,"TWAI TX当前队列接近满");
else if(val("twaiTxQueue")>8)add(1,"TWAI TX当前队列偏高");
else if(val("twaiTxQueueMax")>14)note("TWAI TX队列历史曾接近满载，当前稳定");
else if(val("twaiTxQueueMax")>8)note("TWAI TX队列历史偏高，当前稳定");
if(val("can1TxMaxUs")>5000)add(2,"bus=1 TX耗时超过5ms");
else if(val("can1TxMaxUs")>2000||val("can1TxSlowCount")>0)add(1,"bus=1 TX耗时超过2ms");
if(val("canbOverflowDelta")>0)add(2,"MCP2515 RX overflow刚增加");
else if(val("canbRxOverflowCount")>0)note("MCP2515 RX overflow历史异常，当前稳定");
const system=lastSystemStatus||{},systemHealth=system.health||{},canRt=system.loops&&system.loops.canRt,canRtAge=Number(canRt&&canRt.lastSeenAgeMs);
if(Number.isFinite(canRtAge)&&canRtAge<4294967295){if(canRtAge>3000)add(2,"CAN 实时循环超过3秒无心跳（CPU0任务可能未运行）");else if(canRtAge>1000)add(1,"CAN 实时循环心跳延迟超过1秒")}
if(lastCanDiag&&Array.isArray(lastCanDiag.buses)){
  [0,1,2].forEach(controller=>{const bus=lastCanDiag.buses.find(item=>Number(item.controller)===controller);if(!bus)return;const name="CAN"+controller;if(bus.userDisabled)note(name+"已由用户关闭");else if(!bus.available)add(2,name+"控制器不可用");else if(bus.busOff)add(2,name+"控制器 Bus-Off");else if(bus.recovering)add(1,name+"控制器恢复中");else if(!bus.running)add(2,name+"控制器未运行");else {const age=Number(bus.runtimeInputAgeMs);if(Number.isFinite(age)&&age<4294967295&&age>2500)add(1,name+"车辆输入超过2.5秒未更新")}})
}
if(inc("canbRxQueueDropCount")>0)add(2,"CAN2 CPU0接收队列刚发生丢弃");
else if(val("canbRxQueueDropCount")>0)note("CAN2接收队列存在历史丢弃");
if(val("canbRxQueueMaxDepth")>112)add(2,"CAN2接收队列最近接近128帧满载");
else if(val("canbRxQueueMaxDepth")>80)add(1,"CAN2接收队列最近峰值偏高");
if(inc("canbBacklogCount")>0)add(1,"MCP2515 RX backlog刚增加");
if(val("canbErrorFlags")!==0)add(1,"MCP2515 EFLG非0");
if(val("canbDrainMaxUs")>1500)add(2,"MCP2515 drain耗时超过1.5ms");
else if(val("canbDrainMaxUs")>=900)add(1,"MCP2515 drain触及900us预算");
if(val("canbDrainMaxFrames")>=24)add(1,"MCP2515单轮drain达到活动预算");
if(val("canbTxMaxUs")>5000)add(2,"bus=2 TX耗时超过5ms");
else if(val("canbTxMaxUs")>2000||val("canbTxSlowCount")>0)add(1,"bus=2 TX耗时超过2ms");
if(val("canbTxFailRate")>0)add(1,"bus=2发送失败增加");
if(inc("canbSpiFaultCount")>0)add(2,"MCP2515 SPI寄存器校验失败增加");
if(inc("canbControllerTxFailCount")>0)add(1,"MCP2515 控制器TX失败增加");
if(inc("canbTxBusyCount")>0)note("MCP2515发送邮箱忙，已延迟重试");
if(inc("canbServiceFailedCount")>0)add(1,"0x339诊断帧最终失败增加");
if(inc("canbTxSchedDrop")>0)add(2,"MCP2515 TX调度队列丢弃增加");
if(inc("canbTxSchedExpired")>0)add(1,"MCP2515 TX调度队列过期增加");
if(inc("canbTxSchedFail")>0)add(1,"MCP2515 TX调度发送失败增加");
if(inc("canbTxSchedBudgetHit")>0)add(1,"MCP2515 TX调度单轮预算触顶");
const reportedLevel=normalizedHealthLevel("level" in systemHealth?systemHealth.level:j.systemHealthLevel),reportedReason=String(systemHealth.reason||"");
if(reportedLevel>0&&reportedReason&&reportedReason!=="ok"&&!reportedReason.startsWith("can_rt_"))add(reportedLevel,"板卡健康监控："+reportedReason);
items.sort((a,b)=>b.sev-a.sev);
