const adviceEl=document.getElementById("autoDiagAdvice");
if(levelEl){levelEl.textContent=levelText;levelEl.style.color=level===2?"#f66":(level===1?"#ffd479":"#9f9")}
const normalSummary=system.cpu&&system.cpu.warmingUp?"系统健康检查正常；CPU采样预热中":"当前未发现系统健康异常";
if(reasonEl)reasonEl.textContent=items.length?items.slice(0,5).map(x=>(x.sev===2?"严重：":(x.sev===1?"警告：":"状态："))+x.msg).join("；"):normalSummary;
