async function validateOtaFile(file,maxSize){
  if(!file||!file.name.toLowerCase().endsWith(".bin"))throw new Error("请选择 OTA BIN 固件文件");
  if(file.size<288)throw new Error("固件文件为空或不完整");
  if(!maxSize||file.size>maxSize)throw new Error("文件超过 OTA 分区上限；线刷包请使用 USB 线刷");
  const buffer=await file.slice(0,288).arrayBuffer();
  if(buffer.byteLength<288)throw new Error("无法完整读取固件文件");
  const view=new DataView(buffer);
  if(view.getUint8(0)!==0xe9||view.getUint16(12,true)!==0x12)throw new Error("不是 ESP32-P4 固件");
  if(view.getUint32(32,true)!==0xabcd5432)throw new Error("请选择 application-only OTA 文件，不能使用线刷包");
}
async function startOta(){
  if(otaBusy)return;
  const file=document.getElementById("otaFile").files[0],progress=document.getElementById("otaProgress");
  let token=otaToken;
  if(!token){setOtaMessage("升级令牌不可用，请通过设备热点 IP 或外部 IP 重新打开页面",true);return}
  if(autoSaveBusy||autoSaveTimer||rearFogSaveTimer||bleObstacleSavePending||rearFogSaveBusy||torqueNagSaveInFlight||(typeof ussRadarLoadInFlight!=="undefined"&&ussRadarLoadInFlight)||(typeof ussRadarSaveBusy!=="undefined"&&ussRadarSaveBusy)||(typeof ussRadarSaveTimer!=="undefined"&&ussRadarSaveTimer)){setOtaMessage("参数正在保存或读取，请完成后再开始升级",true);return}
  if(coreDumpDownloadInFlight||diagnosticDownloadInFlight){setOtaMessage("诊断文件正在下载，请下载完成后再升级",true);return}
  localOtaBusy=true;refreshOtaBusy();setOtaControlsDisabled(true);
  if(progress)progress.value=0;
  let startAttempted=false,uploadSent=false;
  try{
    setOtaMessage("正在检查固件文件...",false);
    await validateOtaFile(file,otaMaxSize);
    await dashboardReads.pause();
    setOtaMessage("正在安全停止 CAN 发送...",false);
    startAttempted=true;
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
    try{
      const start=await fetch("/ota/start",{method:"POST",headers:{"X-T2CAN-OTA-Token":token},signal:controller.signal}),startText=await start.text();
      if(!start.ok){startAttempted=false;throw new Error(otaErrorText(startText,start.status))}
      const started=JSON.parse(startText);
      if(!/^[0-9a-f]{32}$/.test(started.token||""))throw new Error("升级授权响应不完整，请刷新升级状态");
      token=started.token;otaToken=token;
    }finally{clearTimeout(timer)}
    setOtaMessage("正在上传固件，请保持供电和连接",false);
    await new Promise((resolve,reject)=>{
      const xhr=new XMLHttpRequest();xhr.open("POST","/ota/upload");xhr.timeout=180000;
      xhr.setRequestHeader("Content-Type","application/octet-stream");xhr.setRequestHeader("X-T2CAN-OTA-Token",token);
      xhr.upload.onprogress=e=>{if(e.lengthComputable&&progress)progress.value=Math.min(99,Math.round(e.loaded*100/e.total));if(e.lengthComputable&&e.loaded===e.total)setOtaMessage("文件已发送，等待设备校验和确认...",false)};
      xhr.onload=()=>{
        if(xhr.status!==200){reject(new Error(otaErrorText(xhr.responseText,xhr.status)));return}
        try{const result=JSON.parse(xhr.responseText);if(!result.ok||Number(result.bytes)!==file.size)throw new Error("设备确认信息不完整，升级结果尚未确认，请重新连接后核对版本");resolve(result)}catch(e){reject(new Error("设备确认信息不完整，升级结果尚未确认，请重新连接后核对版本"))}
      };
      const uncertain=reason=>reject(new Error(reason+"，升级结果尚未确认；请重新连接设备后核对版本和升级状态"));
      xhr.onerror=()=>uncertain("上传连接中断");xhr.ontimeout=()=>uncertain("上传超时");xhr.onabort=()=>uncertain("上传已中断");
      uploadSent=true;xhr.send(file);
    });
    if(progress)progress.value=100;
    setOtaMessage("固件写入和校验成功，设备正在重启；重新连接后查看版本和启动健康验证结果",false);
  }catch(e){
    if(startAttempted){
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);
      try{await fetch("/ota/cancel",{method:"POST",headers:{"X-T2CAN-OTA-Token":token},signal:controller.signal})}catch(cancelError){}finally{clearTimeout(timer)}
    }
    localOtaBusy=false;dashboardReads.resume();refreshOtaBusy();setOtaControlsDisabled(false);
    setOtaMessage((uploadSent?"升级未完成确认：":"无法开始升级：")+(e.name==="AbortError"?"设备响应超时，请重新连接后查看升级状态":e.message),true);
    setTimeout(loadOtaStatus,1200);
  }
}

