  const groups={on:[],off:[],unknown:[],items:[],allItems:[]};
  const itemFor=([key,name])=>{const value=features&&features[key],kind=value===true?"on":value===false?"off":"unknown";return {key,name,kind}};
  allNames.forEach(item=>groups.allItems.push(itemFor(item)));
  names.forEach(item=>{const displayItem=itemFor(item);groups[displayItem.kind].push(displayItem.name);groups.items.push(displayItem)});return groups;
