function renderDriverProfiles(snapshot){
  driverProfilesSnapshot=snapshot||null;
  if(typeof ambientEnsureDriver==='function')ambientEnsureDriver();
  renderDriverRecognitionModeButton(snapshot);
  refreshDriverBindingDialogs();
  const drivers=Array.isArray(snapshot&&snapshot.drivers)?snapshot.drivers:[];
  const activeId=Number(snapshot&&snapshot.activeDriverId)||0;
  const active=drivers.find(driver=>Number(driver.id)===activeId)||drivers.find(driver=>driver.active);
  setText("driverActiveName",active?active.name:(activeId?"驾驶员 #"+activeId:"未选择"));
  setText("driverRecognitionState",driverRecognitionText(snapshot&&snapshot.recognitionState));
  setText("driverBindingState",driverBindingText(snapshot&&snapshot.bindingState));
  setText("driverParameterMode",driverParameterMode(snapshot));
  const list=document.getElementById("driverProfileList");
  if(!list)return;
  list.replaceChildren();
  if(!drivers.length){
    const empty=document.createElement("p");empty.className="driverEmpty";empty.textContent="尚无驾驶员档案";list.appendChild(empty);return;
  }
  drivers.slice().sort((a,b)=>Number(b.lastUseSequence||0)-Number(a.lastUseSequence||0)).forEach(driver=>{
    const id=Number(driver.id),row=document.createElement("div");row.className="driverRow";row.dataset.driverId=String(id);
    const identity=document.createElement("div");identity.className="driverIdentity";
    const name=document.createElement("b");name.textContent=driver.name||("驾驶员 #"+id);
    const last=document.createElement("small");last.textContent="最近使用 #"+(Number(driver.lastUseSequence)||0);identity.append(name,last);
    const badges=document.createElement("div");badges.className="driverBadges";
    if(driver.active||id===activeId)badges.appendChild(driverBadge("当前","current"));else badges.appendChild(driverBadge("非当前"));
    if(driver.manual)badges.appendChild(driverBadge("手动"));
    badges.appendChild(driverBadge(driver.bindingDirty?"位置不匹配":"已保存",driver.bindingDirty?"warn":"saved"));
    const actions=document.createElement("div");actions.className="driverActions";
    const select=document.createElement("button");select.type="button";select.textContent="选择";select.disabled=id===activeId;select.addEventListener("click",()=>selectDriverProfile(id));
    const rebind=document.createElement("button");rebind.type="button";rebind.textContent="重新绑定";rebind.addEventListener("click",()=>openDriverRebindModal(id));
    const rename=document.createElement("button");rename.type="button";rename.textContent="编辑名称";rename.addEventListener("click",()=>openDriverRenameModal(id));
    const remove=document.createElement("button");remove.type="button";remove.className="warn";remove.textContent="删除";remove.addEventListener("click",()=>deleteDriverProfile(id));
    actions.append(select,rebind,rename,remove);
    const features=renderDriverFeatureSnapshot(driver,driver.active||id===activeId);
    row.append(identity,badges,features.preview,features.details,actions);list.appendChild(row);
  });
}
async function loadDriverProfiles(showMessage=true){
  if(!managementDashboardReadsAllowed()){if(driverProfilesTimer){clearTimeout(driverProfilesTimer);driverProfilesTimer=null}return driverProfilesSnapshot}
  if(driverProfilesInFlight)return driverProfilesSnapshot;
  if(driverProfilesTimer){clearTimeout(driverProfilesTimer);driverProfilesTimer=null}
  driverProfilesInFlight=true;const managementGeneration=managementReadGeneration;
  const modeEpoch=driverProfilesModeEpoch;
  try{
    const snapshot=await fetchDashboardJson("/driver_profiles",8000);
    if(modeEpoch!==driverProfilesModeEpoch||!managementDashboardReadsAllowed()||managementGeneration!==managementReadGeneration)return driverProfilesSnapshot;
    if(!snapshot||snapshot.ok!==true||!Array.isArray(snapshot.drivers))throw new Error("响应无效");
    if(driverFeatureSaveInFlight)return driverProfilesSnapshot;
    renderDriverProfiles(snapshot);setDriverSettingsMessage("");
    if(typeof speedTargetEnsureDriver==='function')void speedTargetEnsureDriver();
    observeDriverForPageRefresh(snapshot);
    return snapshot;
  }catch(error){
    if(modeEpoch!==driverProfilesModeEpoch||!managementDashboardReadsAllowed()||managementGeneration!==managementReadGeneration)return driverProfilesSnapshot;
    if(showMessage&&!isDashboardReadCancelled(error))setDriverSettingsMessage("无法读取驾驶员设置："+error.message,"bad");
    driverProfilesSnapshot=null;refreshDriverBindingDialogs();return null;
  }finally{
    driverProfilesInFlight=false;if(managementDashboardReadsAllowed()&&(managementGeneration===managementReadGeneration))driverProfilesInitialLoadDone=true;syncDriverProfilesPolling();
  }
}
async function postDriverProfile(action,fields={}){
  const params=new URLSearchParams();params.set("action",action);
  if(action==="add")params.set("name",String(fields.name||""));
  else if(action==="select"||action==="rebind"||action==="delete")params.set("id",String(fields.id));
  else if(action==="rename"){params.set("id",String(fields.id));params.set("name",String(fields.name||""))}
  else if(action!=="auto"&&action!=="manual")throw new Error("不支持的驾驶员操作");
  if(["add","select","delete","auto","manual"].includes(action)&&typeof ambientSaveBeforeDriverChange==="function"&&!await ambientSaveBeforeDriverChange())throw new Error("氛围灯设置尚未成功保存，驾驶员操作已取消；请重试保存后再操作");
  const response=await fetch("/driver_profiles",{method:"POST",body:params,cache:"no-store"});
  const payload=await response.json().catch(()=>({}));
  if(!response.ok||payload.ok===false){
    const conflict=payload.error==="position_conflict";
    const fallback=conflict?"position_conflict":("HTTP "+response.status);
    const errorText={vehicle_not_parked:"请挂入 P 挡后再操作驾驶员设置",seat_position_stale:"当前没有有效的新鲜驾驶位数据",driver_storage_full:"驾驶员存储空间不足",driver_not_found:"找不到该驾驶员",invalid_name:"驾驶员名称无效",flash_write:"驾驶员设置写入 Flash 失败"}[payload.error];const message=conflict?("位置与“"+(payload.conflictName||("驾驶员 #"+payload.conflictId))+"”冲突，已阻止覆盖"):(errorText||payload.error||fallback);
    const error=new Error(message);error.driverConflict=conflict?payload:null;throw error;
  }
  if(typeof cloudMarkSettingsSaved==='function')cloudMarkSettingsSaved();
  return payload;
}
